/**
 * Measures the production build of the homepage with Lighthouse and writes the
 * scores to src/config/lighthouse.generated.ts, which the homepage's "audit"
 * section displays. The numbers on the site therefore always come from a real
 * run, never from someone typing them in.
 *
 *   npm run build && npm run measure
 *
 * Runs mobile and desktop three times each and keeps the median run (by
 * performance score), because single Lighthouse runs vary. Requires Google
 * Chrome installed locally. Commit the generated file after running.
 */
import { spawn, execFileSync } from 'node:child_process'
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

const PORT = 4174
const URL = `http://localhost:${PORT}/`
const RUNS = 3
const OUT = 'src/config/lighthouse.generated.ts'
const CATEGORIES = ['performance', 'accessibility', 'best-practices', 'seo']

const preview = spawn('npx', ['vite', 'preview', '--port', String(PORT), '--strictPort'], { stdio: 'ignore' })
const stop = () => preview.kill()
process.on('exit', stop)

const waitForServer = async () => {
  for (let i = 0; i < 60; i++) {
    try {
      if ((await fetch(URL)).ok) return
    } catch {
      // not up yet
    }
    await new Promise(r => setTimeout(r, 500))
  }
  throw new Error(`preview server did not start on ${URL}`)
}

const run = (preset, dir, n) => {
  const out = join(dir, `${preset}-${n}.json`)
  const args = [
    '-y', 'lighthouse@12', URL, '--quiet',
    '--chrome-flags=--headless=new',
    `--only-categories=${CATEGORIES.join(',')}`,
    '--output=json', `--output-path=${out}`,
  ]
  if (preset === 'desktop') args.push('--preset=desktop')
  execFileSync('npx', args, { stdio: 'ignore' })
  const report = JSON.parse(readFileSync(out, 'utf8'))
  const scores = Object.fromEntries(CATEGORIES.map(c => [c, Math.round(report.categories[c].score * 100)]))
  return { scores, version: report.lighthouseVersion }
}

await waitForServer()
const dir = mkdtempSync(join(tmpdir(), 'exorit-lh-'))
const result = {}
let version = ''

for (const preset of ['mobile', 'desktop']) {
  const runs = []
  for (let n = 0; n < RUNS; n++) {
    const r = run(preset, dir, n)
    version = r.version
    runs.push(r.scores)
    console.log(preset, n + 1, JSON.stringify(r.scores))
  }
  runs.sort((a, b) => a.performance - b.performance)
  result[preset] = runs[Math.floor(runs.length / 2)]
}

const file = `// Generated by scripts/measure-lighthouse.mjs — do not edit by hand.
// Re-run with: npm run build && npm run measure

export interface LighthouseScores {
  performance: number
  accessibility: number
  'best-practices': number
  seo: number
}

export const lighthouse: {
  measuredAt: string
  tool: string
  mobile: LighthouseScores
  desktop: LighthouseScores
} | null = ${JSON.stringify(
  { measuredAt: new Date().toISOString().slice(0, 10), tool: `Lighthouse ${version}`, ...result },
  null,
  2
)}
`
writeFileSync(OUT, file)
console.log(`wrote ${OUT}`)
stop()
process.exit(0)
